import pptx
from pptx.enum.shapes import MSO_SHAPE_TYPE
import os

prs = pptx.Presentation("input.pptx")

print("Inspecting slides...")
for i, slide in enumerate(prs.slides):
    print(f"Slide {i+1}:")
    for shape in slide.shapes:
        if shape.has_text_frame:
            print(f"  Text Shape: '{shape.text.strip()}'")

        if shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
            print(f"  OLE Object found. Name: {shape.name}")
            # Try to get part name to match with zip contents later
            try:
                part = shape.part
                print(f"    Partname: {part.partname}")
                # print(f"    Blob length: {len(part.blob)}")
            except Exception as e:
                print(f"    Could not access part: {e}")

